        this.trackingCode = trackingCode;
    }

    public boolean isPaidWithinTimeout(long timeoutMillis) {
        if (this.paidAt == null) {
            return false;
        }
        long elapsed = this.paidAt.toEpochMilli() - this.createdAt.toEpochMilli();
        return elapsed <= timeoutMillis;
    }
}

